        a = stack.pop()
        if op == '+':
            stack.append(a + b)
        elif op == '-':
            stack.append(a - b)
        elif op == '*':
            stack.append(a * b)
        elif op == '/':
            stack.append(a // b)

    def apply_operator(stack, operators, op):
        if len(operators) > 0 and (operators[-1] in '*/' and op in '*/'):
            while len(operators) > 0 and operators[-1] in '*/':
                calculate(stack, operators.pop(), None)
        operators.append(op)

    def parse_expression(expr):
        stack = []
        operators = []
        i = 0
        while i < len(expr):
            if expr[i].isdigit():
                j = i
                while j < len(expr) and expr[j].isdigit():
                    j += 1
                stack.append(int(expr[i:j]))
                i = j
            elif expr[i] in '+-*/':
                while len(operators) > 0 and operators[-1] != '(':
                    calculate(stack, operators.pop(), None)
                operators.append(expr[i])
                i += 1
            elif expr[i] == '(':
                operators.append(expr[i])
                i += 1
            elif expr[i] == ')':
                while operators[-1] != '(':
                    calculate(stack, operators.pop(), None)
                operators.pop()
                i += 1
        while len(operators) > 0:
            calculate(stack, operators.pop(), None)
        return stack[0]

    return parse_expression(expr.replace(' ', ''))

